    DateTime? createdAt,
    DateTime? updatedAt,
    bool? isArchived,
    bool? isFallback,
  }) => Category(
    id: id ?? this.id,
    bookId: bookId ?? this.bookId,
    name: name ?? this.name,
    kind: kind ?? this.kind,
    parentId: parentId.present ? parentId.value : this.parentId,
    createdAt: createdAt ?? this.createdAt,
